"""The Python-facing collector: gather constants during analysis, write one .tex file."""

from __future__ import annotations

import datetime
import os
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Sequence, Union

from .groups import Group, _check_name
from .numbers import format_bool, format_value, is_bool

__all__ = ["Context", "Constant"]

_HEADER = (
    "% ---- Generated by factpin {version} ----\n"
    "% ---- Output date: {date} ----\n"
)


def _check_text(name: str, text: Any) -> str:
    """Validate a text constant's payload.

    The text is raw LaTeX and is passed through untouched, so ``\\textsc{ABC}`` and
    friends work. Only the three things that would corrupt the *generated file itself*
    are rejected: a newline splits the one-declaration-per-line format, an unbalanced
    brace swallows everything after it, and an unescaped ``%`` comments out the closing
    brace. All three fail far from their cause, so they are caught here instead.
    """
    if not isinstance(text, str):
        raise TypeError(
            f"constant {name!r}: text must be a str, got {type(text).__name__!r}"
        )
    if not text.strip():
        raise ValueError(f"constant {name!r}: text must not be empty")
    if "\n" in text or "\r" in text:
        raise ValueError(f"constant {name!r}: text must be a single line")

    # Walk once, skipping the character after each backslash so escaped braces and
    # percents are not miscounted.
    depth = 0
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == "\\":
            i += 2
            continue
        if ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth < 0:
                raise ValueError(f"constant {name!r}: text has an unbalanced '}}'")
        elif ch == "%":
            raise ValueError(
                f"constant {name!r}: text has an unescaped '%'; write '\\%' instead"
            )
        i += 1
    if depth:
        raise ValueError(f"constant {name!r}: text has {depth} unclosed '{{'")
    return text


class Constant:
    """One pinned constant: a name, one or more raw values, and an optional group.

    A *text* constant carries a single raw-LaTeX string instead of numbers: it has no
    group, since units and rounding are meaningless for a model or cohort name.
    """

    __slots__ = ("name", "values", "group", "text")

    def __init__(
        self, name: str, values: Sequence[str], group: str, text: bool = False
    ) -> None:
        self.name = name
        self.values = list(values)
        self.group = group
        self.text = text

    def render(self) -> str:
        if self.text:
            return "\\declconsttext{%s}{%s}" % (self.name, self.values[0])
        return "\\declconst{%s}{%s}{%s}" % (
            self.name,
            ",".join(self.values),
            self.group,
        )

    def __repr__(self) -> str:  # pragma: no cover - debugging aid
        kind = "text=True" if self.text else f"group={self.group!r}"
        return f"Constant({self.name!r}, {self.values!r}, {kind})"


class Context:
    """Collects constants and writes them to ``<name>.tex``.

    Nothing is written until :meth:`write` is called -- there is no atexit hook and no
    context-manager magic, so a crashed run never leaves a half-populated results file
    that the manuscript would silently pick up.
    """

    def __init__(
        self,
        name: str,
        path: Union[str, "os.PathLike[str]"] = ".",
        *,
        date: Optional[datetime.date] = None,
    ) -> None:
        _check_name(name, "context")
        self.name = name
        self.path = Path(path)
        self.date = date
        self._groups: Dict[str, Group] = {}
        self._constants: Dict[str, Constant] = {}

    # -- declaration ---------------------------------------------------------

    def add_group(self, name: str, **kwargs: Any) -> Group:
        """Declare a unit/formatting profile. See :class:`~factpin.groups.Group`."""
        if name in self._groups:
            raise ValueError(f"group {name!r} is already declared")
        group = Group(name=name, **kwargs)
        self._groups[name] = group
        return group

    def add(
        self,
        name: str,
        *,
        value: Any = None,
        values: Optional[Iterable[Any]] = None,
        group: Optional[str] = None,
        overwrite: bool = False,
    ) -> Constant:
        """Pin a constant.

        Pass ``value=`` for a scalar or ``values=`` for a tuple such as an estimate with
        a confidence interval; the group's format decides how the parts are typeset.
        """
        _check_name(name, "constant")

        if (value is None) == (values is None):
            raise ValueError(
                f"constant {name!r}: pass exactly one of value= or values="
            )

        if values is not None:
            items = list(values)
            if not items:
                raise ValueError(f"constant {name!r}: values= must not be empty")
        else:
            items = [value]

        if any(is_bool(v) for v in items):
            # A bool has nothing for siunitx to round or format, so it becomes a text
            # constant. That only makes sense for a lone value outside any group.
            if values is not None or group is not None:
                raise TypeError(
                    f"constant {name!r}: a bool must be pinned alone with value= "
                    "and no group"
                )
            self._check_unpinned(name, overwrite)
            constant = Constant(
                name=name, values=[format_bool(value)], group="", text=True
            )
            self._constants[name] = constant
            return constant

        if group is not None:
            if group not in self._groups:
                known = ", ".join(sorted(self._groups)) or "none declared yet"
                raise ValueError(
                    f"constant {name!r}: unknown group {group!r} (known groups: {known})"
                )
            # A lone value always renders plain, so a group may hold both a scalar and
            # the interval that goes with it. The format only governs multi-value
            # constants, and there the count has to match.
            arity = self._groups[group].arity
            if arity is not None and len(items) > 1 and len(items) != arity:
                fmt = self._groups[group].format
                raise ValueError(
                    f"constant {name!r}: format {fmt!r} of group {group!r} expects "
                    f"{arity} value(s), got {len(items)}"
                )

        self._check_unpinned(name, overwrite)

        constant = Constant(
            name=name,
            values=[format_value(v) for v in items],
            group=group or "",
        )
        self._constants[name] = constant
        return constant

    def add_text(
        self, name: str, text: str, *, overwrite: bool = False
    ) -> Constant:
        """Pin a piece of raw LaTeX -- a model name, a cohort label, a units-free word.

        Text constants exist so that prose which *names* the winning configuration stays
        as tied to the analysis as the numbers beside it. They take no group: there is
        nothing for siunitx to round or annotate.
        """
        _check_name(name, "constant")
        _check_text(name, text)
        self._check_unpinned(name, overwrite)

        constant = Constant(name=name, values=[text], group="", text=True)
        self._constants[name] = constant
        return constant

    def _check_unpinned(self, name: str, overwrite: bool) -> None:
        if name in self._constants and not overwrite:
            raise ValueError(
                f"constant {name!r} is already pinned; pass overwrite=True if that is "
                "intentional"
            )

    # -- inspection ----------------------------------------------------------

    @property
    def groups(self) -> List[Group]:
        return list(self._groups.values())

    @property
    def constants(self) -> List[Constant]:
        return list(self._constants.values())

    def __contains__(self, name: str) -> bool:
        return name in self._constants

    def __len__(self) -> int:
        return len(self._constants)

    # -- output --------------------------------------------------------------

    @property
    def output_path(self) -> Path:
        return self.path / f"{self.name}.tex"

    def render(self) -> str:
        """Return the full contents of the generated .tex file."""
        from . import __version__

        date = self.date or datetime.date.today()
        lines = [_HEADER.format(version=__version__, date=date.isoformat())]

        for group in self._groups.values():
            lines.append(
                "\\declconstgroup{%s}{%s}{%s}{%s}"
                % (group.name, group.siunitx_options(), group.unit, group.format)
            )
        if self._groups:
            lines.append("")

        for constant in self._constants.values():
            lines.append(constant.render())

        return "\n".join(lines) + "\n"

    def write(self, path: Union[str, "os.PathLike[str]", None] = None) -> Path:
        """Write the generated .tex file and return where it landed."""
        target = Path(path) if path is not None else self.output_path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(self.render(), encoding="utf-8")
        return target
